'use client'

import { useEffect, useMemo, useRef, useState, type KeyboardEvent } from 'react'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import styles from './Calendar.module.css'

/* ------------------------------------------------------------ plain dates
   Calendar dates carry no time: every Date here is local midnight. */

export const startOfDay = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate())
export const isSameDay = (a: Date | null | undefined, b: Date | null | undefined) =>
  !!a && !!b && a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate()
export const addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n)
/** Adds months, keeping the day where it exists: 31 Jan + 1 month is 28/29 Feb. */
export const addMonths = (d: Date, n: number) => {
  const first = new Date(d.getFullYear(), d.getMonth() + n, 1)
  const last = new Date(first.getFullYear(), first.getMonth() + 1, 0).getDate()
  return new Date(first.getFullYear(), first.getMonth(), Math.min(d.getDate(), last))
}
const startOfMonth = (d: Date) => new Date(d.getFullYear(), d.getMonth(), 1)
const clamp = (d: Date, min?: Date | null, max?: Date | null) =>
  min && d < startOfDay(min) ? startOfDay(min) : max && d > startOfDay(max) ? startOfDay(max) : d

/** The locale's first day of the week (0 = Sunday), where the browser knows it. */
export function firstDayOfWeek(locale?: string) {
  try {
    const l = new Intl.Locale(locale ?? navigator.language) as Intl.Locale & {
      getWeekInfo?: () => { firstDay: number }
      weekInfo?: { firstDay: number }
    }
    const info = l.getWeekInfo?.() ?? l.weekInfo
    if (info) return info.firstDay % 7
  } catch {
    /* fall through */
  }
  return 1
}

/** A span of days; `end` is null while only the first end is picked. */
export interface DateRange {
  start: Date | null
  end: Date | null
}

export interface CalendarProps {
  value?: Date | null
  defaultValue?: Date | null
  onValueChange?: (date: Date) => void
  /** The month shown; defaults to the value's, or today's. */
  month?: Date
  defaultMonth?: Date
  onMonthChange?: (month: Date) => void
  min?: Date | null
  max?: Date | null
  /** Rules out single dates, e.g. weekends or booked days. */
  isDateDisabled?: (date: Date) => boolean
  /** Shows a span instead of `value`: both ends selected, the days between banded. Clicks still report one day; the owner decides the span. */
  range?: DateRange | null
  /** BCP 47 tag, e.g. `vi-VN`. Defaults to the browser's. */
  locale?: string
  /** 0 = Sunday … 6 = Saturday. Defaults to the locale's. */
  weekStartsOn?: number
  /** Focus the selected (or today's) day on mount, e.g. when opened in a popover. */
  autoFocus?: boolean
  className?: string
}

export function Calendar({
  value,
  defaultValue = null,
  onValueChange,
  month: monthProp,
  defaultMonth,
  onMonthChange,
  min,
  max,
  isDateDisabled,
  range,
  locale,
  weekStartsOn,
  autoFocus = false,
  className,
}: CalendarProps) {
  const today = startOfDay(new Date())
  const [valueState, setValueState] = useState(defaultValue)
  const selected = range ? range.start : value !== undefined ? value : valueState
  const rangeEnd = range?.end ?? null
  const [monthState, setMonthState] = useState(() => startOfMonth(defaultMonth ?? selected ?? today))
  const month = monthProp ? startOfMonth(monthProp) : monthState
  // The day with the roving tab stop, and where the keyboard moves from.
  const [focused, setFocused] = useState(() => clamp(selected ?? (isSameMonth(today, month) ? today : month), min, max))
  const gridRef = useRef<HTMLTableElement>(null)
  const moveFocus = useRef(autoFocus)

  const first = weekStartsOn ?? firstDayOfWeek(locale)
  const fmt = useMemo(() => {
    return {
      title: new Intl.DateTimeFormat(locale, { month: 'long', year: 'numeric', calendar: 'gregory' }),
      weekday: new Intl.DateTimeFormat(locale, { weekday: 'short', calendar: 'gregory' }),
      weekdayNarrow: new Intl.DateTimeFormat(locale, { weekday: 'narrow', calendar: 'gregory' }),
      weekdayLong: new Intl.DateTimeFormat(locale, { weekday: 'long', calendar: 'gregory' }),
      day: new Intl.DateTimeFormat(locale, { day: 'numeric', calendar: 'gregory' }),
      full: new Intl.DateTimeFormat(locale, { dateStyle: 'full', calendar: 'gregory' }),
    }
  }, [locale])

  const disabled = (d: Date) =>
    (!!min && d < startOfDay(min)) || (!!max && d > startOfDay(max)) || (isDateDisabled?.(d) ?? false)

  const setMonth = (m: Date) => {
    const next = startOfMonth(m)
    setMonthState(next)
    onMonthChange?.(next)
  }
  const focusDay = (d: Date) => {
    const next = clamp(d, min, max)
    setFocused(next)
    if (!isSameMonth(next, month)) setMonth(next)
    moveFocus.current = true
  }
  useEffect(() => {
    if (!moveFocus.current) return
    moveFocus.current = false
    gridRef.current?.querySelector<HTMLElement>('[tabindex="0"]')?.focus()
  })
  // Keep the tab stop inside the month when it changes from outside.
  useEffect(() => {
    if (!isSameMonth(focused, month)) setFocused(clamp(selected && isSameMonth(selected, month) ? selected : month, min, max))
  }, [month.getTime()]) // eslint-disable-line react-hooks/exhaustive-deps

  const select = (d: Date) => {
    if (disabled(d)) return
    setValueState(d)
    onValueChange?.(d)
    setFocused(d)
  }

  const onKeyDown = (e: KeyboardEvent<HTMLElement>) => {
    const dow = (focused.getDay() - first + 7) % 7
    // Right to left mirrors the grid, so the arrows follow what is on screen.
    const ahead = getComputedStyle(e.currentTarget).direction === 'rtl' ? -1 : 1
    const moves: Record<string, () => Date> = {
      ArrowLeft: () => addDays(focused, -ahead),
      ArrowRight: () => addDays(focused, ahead),
      ArrowUp: () => addDays(focused, -7),
      ArrowDown: () => addDays(focused, 7),
      Home: () => addDays(focused, -dow),
      End: () => addDays(focused, 6 - dow),
      PageUp: () => addMonths(focused, e.shiftKey ? -12 : -1),
      PageDown: () => addMonths(focused, e.shiftKey ? 12 : 1),
    }
    if (moves[e.key]) {
      e.preventDefault()
      focusDay(moves[e.key]())
    } else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      select(focused)
    }
  }

  // Six rows of seven days, starting on the week's first day.
  const lead = (month.getDay() - first + 7) % 7
  const start = addDays(month, -lead)
  const weeks = Array.from({ length: 6 }, (_, w) => Array.from({ length: 7 }, (_, d) => addDays(start, w * 7 + d)))
  const weekdays = weeks[0]
  // Two letters where the short names are short ("Mon" → "Mo", "lun." →
  // "lu"); the narrow ones where they are not ("Thứ 2" → "T2").
  const weekdayName = (d: Date) => {
    const short = fmt.weekday.format(d)
    return weekdays.every((w) => fmt.weekday.format(w).length <= 4) ? short.slice(0, 2) : fmt.weekdayNarrow.format(d)
  }
  const minMonth = min ? startOfMonth(min) : null
  const maxMonth = max ? startOfMonth(max) : null
  const nav = (label: string, months: number) => {
    const back = months < 0
    return (
      <button
        type="button"
        className={styles.nav}
        aria-label={label}
        disabled={back ? !!minMonth && minMonth >= month : !!maxMonth && maxMonth <= month}
        onClick={() => setMonth(clamp(addMonths(month, months), minMonth, maxMonth))}
      >
        <Icon name={back ? 'chevron-left' : 'chevron-right'} className={styles.dirIcon} />
      </button>
    )
  }

  return (
    <div className={cn(styles.calendar, className)}>
      {/* Month back at the start, the month centred, month on at the end.
          Years are Shift+Page Up and Shift+Page Down. */}
      <div className={styles.header}>
        {nav('Previous month', -1)}
        {/* Not a heading: a calendar can sit anywhere in a page's outline.
            It announces the month as it changes. */}
        <div className={styles.title} aria-live="polite">
          {fmt.title.format(month)}
        </div>
        {nav('Next month', 1)}
      </div>
      <table ref={gridRef} role="grid" aria-label={fmt.title.format(month)} className={styles.grid} onKeyDown={onKeyDown}>
        <thead>
          <tr>
            {weekdays.map((d) => (
              <th key={d.getDay()} scope="col" abbr={fmt.weekdayLong.format(d)} className={styles.weekday}>
                {weekdayName(d)}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {weeks.map((week, w) => (
            <tr key={w}>
              {week.map((d, col) => {
                const outside = !isSameMonth(d, month)
                // Selection and the band stay inside the month: a day of the month
                // either side is only there for shape, and two months side by
                // side would otherwise both draw the days where they overlap.
                const isSelected = !outside && (isSameDay(d, selected) || isSameDay(d, rangeEnd))
                const between = !outside && !!selected && !!rangeEnd && d > selected && d < rangeEnd
                const banded = !!rangeEnd && !isSameDay(selected, rangeEnd) && (isSelected || between)
                const isDisabled = disabled(d)
                return (
                  <td
                    key={d.getTime()}
                    role="gridcell"
                    aria-selected={isSelected || between || undefined}
                    className={cn(
                      styles.cell,
                      banded && styles.inRange,
                      banded && isSameDay(d, selected) && styles.rangeStart,
                      banded && isSameDay(d, rangeEnd) && styles.rangeEnd,
                      // Rounded off where a week or the month starts or ends.
                      banded && (col === 0 || d.getDate() === 1) && styles.bandStart,
                      banded && (col === 6 || addDays(d, 1).getDate() === 1) && styles.bandEnd,
                    )}
                  >
                    {outside ? (
                      // The months either side are shape, not content: hidden from
                      // assistive tech, not pickable, and faded past muted. Arrow
                      // keys still cross into them, by moving the month.
                      <span aria-hidden="true" data-outside="" className={cn(styles.day, styles.outside)}>
                        {fmt.day.format(d)}
                      </span>
                    ) : (
                      <button
                        type="button"
                        tabIndex={isSameDay(d, focused) ? 0 : -1}
                        aria-label={fmt.full.format(d)}
                        aria-current={isSameDay(d, today) ? 'date' : undefined}
                        aria-disabled={isDisabled || undefined}
                        className={cn(
                          styles.day,
                          isSelected && styles.selected,
                          between && styles.between,
                          isSameDay(d, today) && styles.today,
                        )}
                        onClick={() => select(d)}
                        onFocus={() => setFocused(d)}
                      >
                        {fmt.day.format(d)}
                      </button>
                    )}
                  </td>
                )
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

function isSameMonth(a: Date, b: Date) {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth()
}

.calendar {
  /* A day is 40 by 32px and the days touch, as @atlaskit/calendar's: seven
     columns at least 2.5rem wide, a 20px line with 4px above and below
     inside a 2px edge. */
  /* Narrower on a screen that cannot hold seven of them (320px, the reflow
     width of WCAG 1.4.10): the popup keeps 16px from each edge and pads 16px. */
  --calendar-day-inline: min(var(--box-lg), calc((100vw - 4.25rem) / 7));
  --calendar-day-block: var(--control-md);
  display: inline-flex;
  flex-direction: column;
  /* 12px from the header to the grid, as Atlassian's. */
  gap: var(--space-3);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  color: var(--color-text);
  font-variant-numeric: tabular-nums;
}

.header {
  display: flex;
  align-items: center;
  /* 8px at each end, as Atlassian's header: the arrows stop 8px short of the
     grid's edges. */
  padding-inline: var(--space-inline);
}

/* The month between the two arrows: they are as wide as each other, so it is
   centred on the grid. A long name on a narrow screen wraps. */
.title {
  flex: 1;
  min-inline-size: 0;
  font-size: var(--text-heading-xs);
  line-height: var(--leading-heading-xs);
  font-weight: 600;
  text-align: center;
}

.nav {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  /* Atlassian's compact icon button: 24px round a 12px chevron. */
  inline-size: var(--control-sm);
  block-size: var(--control-sm);
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--radius-control);
  background: transparent;
  color: var(--color-text);
  font-size: var(--icon-xs);
  cursor: var(--cursor-button);
}
.nav:hover:not(:disabled) {
  background: var(--color-background-neutral);
  color: var(--color-text);
}
.nav:disabled {
  opacity: 0.5;
  cursor: var(--cursor-disabled);
}

.grid {
  border-collapse: collapse;
  /* Keeps the focused day's z-index inside the grid. */
  isolation: isolate;
}

/* 8px round a 16px line: a 32px row, as Atlassian's week header. */
.weekday {
  box-sizing: border-box;
  min-inline-size: var(--calendar-day-inline);
  padding: var(--space-2);
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  font-weight: 600;
  color: var(--color-text-subtlest);
  text-align: center;
  white-space: nowrap;
}

.cell {
  padding: 0;
}

/* The day fills its cell, so the days touch and all of the cell is the
   target. `flex`, not `inline-flex`: an inline box would sit on the cell's
   baseline and make the row taller than the day. Positioned, so the focused
   day can be lifted above its neighbours. */
.day {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  inline-size: var(--calendar-day-inline);
  block-size: var(--calendar-day-block);
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--radius-control);
  background: transparent;
  color: var(--color-text);
  font: inherit;
  cursor: var(--cursor-button);
}
.day:hover:not([aria-disabled='true'], .selected, .outside) {
  background: var(--color-background-neutral);
  color: var(--color-text);
}

/* Days of the next and previous month: shape, not content. Faded past
   --color-text-subtlest so the month reads first; no token is lighter. About
   2:1, which WCAG allows for decoration: they are aria-hidden and not
   pickable. */
.outside {
  color: color-mix(in oklch, var(--color-text-subtlest) 50%, transparent);
  cursor: default;
}

/* Today: the control's shape in orange. The figure is near-black
   (--color-text-accent-orange-contrast, 4.9:1 in both modes): white on the
   orange is 3.4:1 in light, under the 4.5:1 a 14px figure needs. */
.today {
  border-radius: var(--radius-control);
  background: var(--color-background-accent-orange-bolder);
  color: var(--color-text-accent-orange-contrast);
  font-weight: 600;
}
.today:hover:not([aria-disabled='true'], .selected) {
  background: var(--color-background-accent-orange-bolder);
  color: var(--color-text-accent-orange-contrast);
}

/* After .today: a selected today shows as selected. */
.selected {
  border-radius: var(--radius-control);
  background: var(--color-background-brand-bold);
  color: var(--color-text-brand-inverse);
  font-weight: 600;
}

.day[aria-disabled='true'] {
  color: var(--color-text-subtlest);
  text-decoration: line-through;
  opacity: 0.6;
  cursor: var(--cursor-disabled);
}

.day:focus-visible,
.nav:focus-visible {
  outline: var(--focus-width) solid var(--color-border-focused);
  outline-offset: var(--focus-offset);
}
/* The days touch, so the ring lies over the days around it: the focused day
   goes above them, or the next day's fill would cut the ring. */
.day:focus-visible {
  /* stylelint-disable-next-line scale-unlimited/declaration-strict-value -- local stacking inside the grid, not a global layer */
  z-index: 1;
}

/* A range: every cell from one end to the other draws a band behind its
   day, as tall and as wide as the cell. The cells touch, so the band is one
   unbroken strip. Under the two ends it covers only the half that faces the
   range, so the ends keep their own corners on the outside and the band
   meets them in the middle. It rounds off where a week or the month starts
   or ends. Logical insets, so right to left needs nothing. */
.inRange {
  position: relative;
}
.inRange::before {
  content: '';
  position: absolute;
  inset: 0;
  background: var(--color-background-neutral);
}
.rangeStart::before {
  inset-inline-start: 50%;
}
.rangeEnd::before {
  inset-inline-end: 50%;
}
.bandStart:not(.rangeStart)::before {
  border-start-start-radius: var(--radius-control);
  border-end-start-radius: var(--radius-control);
}
.bandEnd:not(.rangeEnd)::before {
  border-start-end-radius: var(--radius-control);
  border-end-end-radius: var(--radius-control);
}
.between {
  color: var(--color-text);
  font-weight: 400;
}
/* Today keeps its figure inside a range too. */
.between.today {
  color: var(--color-text-accent-orange-contrast);
  font-weight: 600;
}

/* 40 by 32px days are below the 44px touch target. They touch, so a larger
   invisible area would lie over the next day: the days themselves grow on
   coarse pointers. The arrows stay 24px and grow an invisible area instead.
   The header makes room: each area reaches 10px past its arrow, the header
   pads that much and the month keeps that much clear, so the areas lie over
   neither the month nor the calendar's edge. */
@media (pointer: coarse) {
  .calendar {
    --calendar-day-inline: min(var(--target-coarse), calc((100vw - 4.25rem) / 7));
    --calendar-day-block: var(--target-coarse);
    --calendar-nav-reach: calc((var(--target-coarse) - var(--control-sm)) / 2);
  }
  .header {
    padding-inline: var(--calendar-nav-reach);
  }
  .title {
    padding-inline: var(--calendar-nav-reach);
  }
  .nav::after {
    content: '';
    position: absolute;
    inset: 50% auto auto 50%;
    inline-size: var(--target-coarse);
    block-size: var(--target-coarse);
    translate: -50% -50%;
  }
}

/* Previous and next point the way the content moves: mirrored right to
   left. Not :dir(rtl): the build lowers it to a list of :lang()s, which
   misses a dir="rtl" page in any other language. */
:global([dir='rtl']) .dirIcon {
  scale: -1 1;
}
:global([dir='rtl'] [dir='ltr']) .dirIcon {
  scale: none;
}
